parameters.query:
insert into flow.sync_runs (job, started_at)
values ('reconcile', now())
returning
  run_id,
  (select (extract(epoch from coalesce(max(r.started_at), now() - interval '48 hours')) - 6*3600)::bigint * 1000
     from flow.sync_runs r where r.job = 'reconcile' and r.ok) as since_ms,
  (select to_char(coalesce(max(r.started_at), now() - interval '48 hours') - interval '6 hours', 'YYYY-MM-DD HH24:MI')
     from flow.sync_runs r where r.job = 'reconcile' and r.ok) as since_human,
  (select drift_warn_threshold from flow.sync_jobs where job = 'reconcile') as drift_threshold;
